import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused CUDA source for ReLU -> LeakyReLU -> GELU -> Sigmoid -> bias addition
fused_activation_bias_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__device__ float gelu(float x) {
    const float kErfInvSqrt2 = 0.70710678118654752440f; // 1/sqrt(2)
    float cdf = 0.5f * (1.0f + erff(x * kErfInvSqrt2));
    return x * cdf;
}

__global__ void fused_activation_bias_kernel(
    const float* input,
    float* output,
    const float* bias,
    int B,
    int C,
    int D,
    int H,
    int W,
    float negative_slope
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int N = B * C * D * H * W;
    if (idx >= N) return;

    float val = input[idx];

    // ReLU
    val = val < 0.0f ? 0.0f : val;

    // LeakyReLU
    if (val < 0.0f) {
        val *= negative_slope;
    }

    // GELU
    val = gelu(val);

    // Sigmoid
    val = 1.0f / (1.0f + expf(-val));

    // Add bias
    int spatialSize = D * H * W;
    int c = (idx / spatialSize) % C;
    val += bias[c];

    output[idx] = val;
}

torch::Tensor fused_activation_bias_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    float negative_slope
) {
    auto B = x.size(0);
    auto C = x.size(1);
    auto D = x.size(2);
    auto H = x.size(3);
    auto W = x.size(4);

    auto output = torch::empty_like(x);
    int N = B * C * D * H * W;

    const int block_size = 256;
    const int grid_size = (N + block_size - 1) / block_size;

    fused_activation_bias_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        bias.data_ptr<float>(),
        B, C, D, H, W,
        negative_slope
    );

    return output;
}
"""

fused_activation_bias_cpp_source = r"""
torch::Tensor fused_activation_bias_cuda(
    torch::Tensor x,
    torch::Tensor bias,
    float negative_slope
);
"""

# Load and compile the fused operator
fused_activation_bias = load_inline(
    name="fused_activation_bias",
    cpp_sources=[fused_activation_bias_cpp_source],
    cuda_sources=[fused_activation_bias_source],
    functions=["fused_activation_bias_cuda"],
    verbose=False
)

class ModelNew(nn.Module):
    """
    Optimized model with fused custom CUDA kernel for activation chain + bias.
    """
    def __init__(self, in_channels, out_channels, kernel_size, bias_shape):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.bias = nn.Parameter(torch.randn(bias_shape))
        self.negative_slope = 0.01

    def forward(self, x):
        x = self.conv(x)
        fused_bias = self.bias.view(-1)  # flatten bias
        x = fused_activation_bias.fused_activation_bias_cuda(x, fused_bias, self.negative_slope)
        return x
